// Independently authored binary vectors; no production encoder creates these oracles.
use super::*;
const GENESIS: &str = "";
const PREVIOUS: &str = "";
const PLAN_SHA: &str = "1f835d7b47a9bcc1d23d8932f3a57c647f3ffda5f53adf5b2082d615dbdb7783";
const INVENTORY_SHA: &str = "4df1749a6629a323de74f500397b4406f3eb1b0c2d6878c10a499338c04e83fc";
const BINDING_SHA: &str = "2ce1795981a5cdc0d08d5abb6e880cce64a90fe8cd83e6828cbf2553d81f7fda";
const PREPARED_SHA: &str = "ea90d0fc0610b1d881ad8e506f7329ef7524b90bf18d27b4337aa5c8308b41b0";

fn bytes(s:&str)->Vec<u8>{assert_eq!(s.len()%2,0);s.as_bytes().chunks_exact(2).map(|c|{let d=|b:u8|match b{b'0'..=b'9'=>b-b'0',b'a'..=b'f'=>b-b'a'+10,_=>panic!("fixture hex")};(d(c[0])<<4)|d(c[1])}).collect()}
fn hh(s:&str)->H{bytes(s).try_into().unwrap()}
fn limits()->Limits{Limits{frame:4096,journal:32768,events:64,plan:8,path:128,version:32}}
fn id(n:u64)->Id{Id{device:9,inode:n}}
fn seed()->Seed{Seed{prior_frame:None,prior_commit:None,prior_prepared:None,anchor:id(1),location:Location::Vacant{parent:id(2),basename:"fresh".into()}}}
fn prior()->Seed{Seed{prior_frame:Some(Tip{seq:11,sha:[0x11;32]}),prior_commit:Some(CommitRef{generation:7,tip:Tip{seq:10,sha:[0x22;32]}}),prior_prepared:Some(PreparedRef{generation:7,digest:[0x33;32]}),anchor:id(1),location:Location::Existing(id(6))}}
fn frames()->Vec<Frame>{decode_journal(&bytes(GENESIS),limits()).unwrap()}
fn intent(f:&Frame)->&Intent{if let Event::Intent(i)=&f.record.event{i}else{panic!("fixture intent")}}

// Independent test-only field writer. Used to give SEMANTIC negative fixtures
// correct checksums, never calls encode_frame or the production Out/Input.
fn w32(b:&mut Vec<u8>,n:u32){b.extend(n.to_be_bytes())}
fn w64(b:&mut Vec<u8>,n:u64){b.extend(n.to_be_bytes())}
fn wt(b:&mut Vec<u8>,s:&str){w32(b,u32::try_from(s.len()).unwrap());b.extend(s.as_bytes())}
fn wi(b:&mut Vec<u8>,i:Id){b.push(1);w64(b,i.device);w64(b,i.inode)}
fn wh(b:&mut Vec<u8>,h:Option<H>){b.push(u8::from(h.is_some()));if let Some(h)=h{b.extend(h)}}
fn wn(b:&mut Vec<u8>,n:Option<u64>){b.push(u8::from(n.is_some()));if let Some(n)=n{w64(b,n)}}
fn wtip(b:&mut Vec<u8>,t:Tip){w64(b,t.seq);b.extend(t.sha)}
fn wc(b:&mut Vec<u8>,c:Option<CommitRef>){b.push(u8::from(c.is_some()));if let Some(c)=c{w64(b,c.generation);wtip(b,c.tip)}}
fn wp(b:&mut Vec<u8>,p:Option<PreparedRef>){b.push(u8::from(p.is_some()));if let Some(p)=p{w64(b,p.generation);b.extend(p.digest)}}
fn wl(b:&mut Vec<u8>,l:&Location){match l{Location::Existing(i)=>{b.push(1);wi(b,*i)},Location::Vacant{parent,basename}=>{b.push(2);wi(b,*parent);wt(b,basename)}}}
fn wplan(b:&mut Vec<u8>,p:&PlanItem){wt(b,&p.path);b.push(p.kind);w32(b,p.mode);w64(b,p.size);wh(b,p.content);wi(b,p.source)}
fn wa(b:&mut Vec<u8>,p:&ActualItem){wt(b,&p.path);b.push(p.kind);wi(b,p.source);wi(b,p.target);w32(b,p.mode);w64(b,p.size);wh(b,p.content);wn(b,p.before);wn(b,p.after)}
fn we(e:&Event)->Vec<u8>{let mut b=Vec::new();match e{
 Event::Intent(i)=>{wt(&mut b,&i.version);wc(&mut b,i.prior_commit);wp(&mut b,i.prior_prepared);wi(&mut b,i.anchor);wl(&mut b,&i.location);wi(&mut b,i.stage);wi(&mut b,i.retained);b.extend(i.seal);w32(&mut b,i.plan.len().try_into().unwrap());for p in &i.plan{wplan(&mut b,p)}},
 Event::Fenced(p)=>wp(&mut b,*p),Event::RootBound{root,location}=>{wi(&mut b,*root);wl(&mut b,location)},
 Event::OpIntent{index,item,expected_absent}=>{w32(&mut b,*index);wplan(&mut b,item);b.push(*expected_absent)},
 Event::OpRecorded{index,item}=>{w32(&mut b,*index);wa(&mut b,item)},
 Event::Commit{root,version,seal,count,inventory}=>{wi(&mut b,*root);wt(&mut b,version);b.extend(seal);w32(&mut b,*count);b.extend(inventory)},
 Event::Ready{commit,root,seal,count,inventory,prepared}=>{wtip(&mut b,*commit);wi(&mut b,*root);b.extend(seal);w32(&mut b,*count);b.extend(inventory);b.extend(prepared)},
 }b}
fn dh(domain:&str,b:&[u8])->H{let mut h=Sha256::new();h.update(domain.as_bytes());h.update([0]);h.update(b);h.finalize().into()}
fn manual(r:&Record)->Vec<u8>{let h=&r.header;let mut p=Vec::new();w32(&mut p,1);p.push(r.event.kind());w64(&mut p,h.seq);w64(&mut p,h.previous_seq);wh(&mut p,h.previous_sha);w64(&mut p,h.generation);p.extend(h.nonce);p.extend(h.binding);p.extend(we(&r.event));let mut b=Vec::new();w32(&mut b,p.len().try_into().unwrap());b.extend(p);let d=dh("openbot.release-transaction.v1",&b);b.extend(d);b}
fn resign(f:&mut[Frame],s:&Seed){let mut prev=s.prior_frame;for f in f{f.record.header.previous_seq=prev.map_or(0,|x|x.seq);f.record.header.previous_sha=prev.map(|x|x.sha);let b=manual(&f.record);f.sha=b[b.len()-32..].try_into().unwrap();prev=Some(Tip{seq:f.record.header.seq,sha:f.sha});}}
fn rebind(f:&mut[Frame]){let mut pre=Vec::new();w64(&mut pre,f[0].record.header.generation);pre.extend(f[0].record.header.nonce);pre.extend(we(&f[0].record.event));let binding=dh("openbot.release-binding.v1",&pre);for x in f.iter_mut(){x.record.header.binding=binding}resign(f,&seed());}
fn repack(b:&mut[u8]){let n=b.len()-32;let h=dh("openbot.release-transaction.v1",&b[..n]);b[n..].copy_from_slice(&h)}
fn fail(f:&[Frame]){assert!(replay(f,&seed(),limits()).is_err())}

#[test] fn literal_full_wire_and_all_four_digest_domains(){let f=frames();let i=intent(&f[0]);assert_eq!(plan_seal(&i.plan,limits()).unwrap(),hh(PLAN_SHA));assert_eq!(binding(1,f[0].record.header.nonce,i,limits()).unwrap(),hh(BINDING_SHA));if let Event::OpRecorded{item,..}=&f[4].record.event{assert_eq!(inventory(&[item.clone()],limits()).unwrap(),hh(INVENTORY_SHA))}else{panic!("fixture")};let r=replay(&f,&seed(),limits()).unwrap();assert_eq!(r.prepared.unwrap().digest,hh(PREPARED_SHA));let mut independent=Vec::new();let mut encoded=Vec::new();for x in &f{independent.extend(manual(&x.record));encoded.extend(encode_frame(&x.record,limits()).unwrap())}assert_eq!(independent,bytes(GENESIS));assert_eq!(encoded,bytes(GENESIS));}
#[test] fn every_legal_prefix_reports_data_phase_and_pending(){let f=frames();let phases=[Phase::Empty,Phase::IntentFixed,Phase::FencedRecorded,Phase::RootBoundRecorded,Phase::Publishing,Phase::Publishing,Phase::ReleaseCommittedNotPrepared,Phase::ReadyRecordDecoded];for n in 0..=7{let r=replay(&f[..n],&seed(),limits()).unwrap();assert_eq!(r.phase,phases[n]);assert_eq!(r.pending,if n==4{Some(0)}else{None})}}
#[test] fn previous_ready_sequence_and_generation_are_distinct_axes(){let f=decode_journal(&bytes(PREVIOUS),limits()).unwrap();assert_eq!(f[0].record.header.seq,12);assert_eq!(f[0].record.header.generation,8);let r=replay(&f,&prior(),limits()).unwrap();assert_eq!(r.tip.unwrap().seq,18);assert_eq!(r.commit.unwrap().tip.seq,17);assert_eq!(r.commit.unwrap().generation,8);}
#[test] fn seed_requires_all_three_prior_fields(){let mut s=prior();s.prior_prepared=None;assert_eq!(replay(&[],&s,limits()).unwrap_err(),Error::Binding);s=prior();s.prior_prepared.as_mut().unwrap().generation=8;assert_eq!(replay(&[],&s,limits()).unwrap_err(),Error::Binding);}
