#[test] fn zero_digest_is_present_data_not_absence(){let mut s=prior();s.prior_frame.as_mut().unwrap().sha=[0;32];s.prior_commit.as_mut().unwrap().tip.sha=[0;32];s.prior_prepared.as_mut().unwrap().digest=[0;32];assert_eq!(replay(&[],&s,limits()).unwrap().phase,Phase::Empty);}
