#[test] fn checksum_and_all_torn_boundaries_rejected(){let good=bytes(GENESIS);let first=manual(&frames()[0].record);for n in [1,3,4,5,30,first.len()-33,first.len()-1]{assert!(decode_journal(&first[..n],limits()).is_err());}let mut b=good.clone();b[20]^=1;assert_eq!(decode_journal(&b,limits()).unwrap_err(),Error::Digest);let mut b=good;b.push(0);assert_eq!(decode_journal(&b,limits()).unwrap_err(),Error::Truncated);}
