#[test] fn strict_utf8_unknown_identity_and_trailing_payload_rejected(){let f=frames();let mut b=manual(&f[0].record);let header_len=4+1+8+8+1+8+16+32;let version_at=4+header_len+4;b[version_at]=0xff;repack(&mut b);assert_eq!(decode_journal(&b,limits()).unwrap_err(),Error::Encoding);let mut b=manual(&f[2].record);let header_len=4+1+8+8+33+8+16+32;b[4+header_len]=2;repack(&mut b);assert_eq!(decode_journal(&b,limits()).unwrap_err(),Error::Identity);let mut b=manual(&f[1].record);let at=b.len()-32;b.insert(at,0);let n=u32::from_be_bytes(b[..4].try_into().unwrap())+1;b[..4].copy_from_slice(&n.to_be_bytes());repack(&mut b);assert_eq!(decode_journal(&b,limits()).unwrap_err(),Error::Encoding);}
