#[test] fn direct_replay_charges_actual_frame_and_total_bytes(){let f=frames();let max=f.iter().map(|x|manual(&x.record).len()).max().unwrap();let sum=f.iter().map(|x|manual(&x.record).len()).sum();let mut l=limits();l.frame=max;l.journal=sum;assert!(replay(&f,&seed(),l).is_ok());l.frame=max-1;assert_eq!(replay(&f,&seed(),l).unwrap_err(),Error::Limit);l.frame=max;l.journal=sum-1;assert_eq!(replay(&f,&seed(),l).unwrap_err(),Error::Limit);}
#[test] fn direct_replay_event_path_version_and_plan_budgets(){let f=frames();let mut l=limits();l.events=6;assert_eq!(replay(&f,&seed(),l).unwrap_err(),Error::Limit);l=limits();l.path=11;assert_eq!(replay(&f,&seed(),l).unwrap_err(),Error::Path);l=limits();l.version=1;assert_eq!(replay(&f,&seed(),l).unwrap_err(),Error::Limit);let mut f=f;let p=intent(&f[0]).plan[0].clone();if let Event::Intent(i)=&mut f[0].record.event{i.plan.push(p)}l=limits();l.plan=1;assert_eq!(replay(&f,&seed(),l).unwrap_err(),Error::Limit);}
#[test] fn decoder_and_encoder_apply_same_frame_limits(){let f=frames();let one=manual(&f[0].record);let mut l=limits();l.frame=one.len();assert_eq!(encode_frame(&f[0].record,l).unwrap(),one);assert_eq!(decode_journal(&one,l).unwrap().len(),1);l.frame-=1;assert_eq!(encode_frame(&f[0].record,l).unwrap_err(),Error::Limit);assert_eq!(decode_journal(&one,l).unwrap_err(),Error::Limit);}
#[test] fn portable_path_reserved_names_and_literal_policy(){
    for path in ["/a","a/","a//b","a/../b","AUX.txt","CON .txt","CONIN$","a\\b","a:b","a.","é"] {
        assert_eq!(portable(path,limits().path),Err(Error::Path));
        let mut f=frames();
        if let Event::Intent(i)=&mut f[0].record.event {
            i.plan[0].path=path.into();
            // Independent test field writer accepts literal bytes without the
            // production path guard. Keep every unrelated digest correct.
            let mut plan_bytes=Vec::new();
            w32(&mut plan_bytes,i.plan.len().try_into().unwrap());
            for item in &i.plan { wplan(&mut plan_bytes,item); }
            i.seal=dh("openbot.release-plan.v1",&plan_bytes);
        }
        rebind(&mut f);
        let result=replay(&f[..1],&seed(),limits());
        assert!(result.is_err());
        assert_eq!(result.unwrap_err(),Error::Path);
    }
    assert!(portable("CONifer.txt",128).is_ok());
}
#[test] fn case_prefix_and_file_ancestor_collision_rejected(){for pair in [("App/a","app/b"),("app","app/b"),("app/a","app/a"),("b","a")]{let mut f=frames();let mut i=intent(&f[0]).clone();i.plan[0].path=pair.0.into();let mut p=i.plan[0].clone();p.path=pair.1.into();p.source=id(8);i.plan.push(p);i.seal=plan_seal(&i.plan,limits()).unwrap();f[0].record.event=Event::Intent(i);rebind(&mut f);assert_eq!(replay(&f[..1],&seed(),limits()).unwrap_err(),Error::Path);}}
#[test] fn regular_source_reuse_and_stage_directory_confusion_rejected(){for source in [id(5),id(3),Id{device:10,inode:8}]{let mut f=frames();let mut i=intent(&f[0]).clone();let mut p=i.plan[0].clone();p.path="app/other.txt".into();p.source=source;i.plan.push(p);i.seal=plan_seal(&i.plan,limits()).unwrap();f[0].record.event=Event::Intent(i);rebind(&mut f);assert_eq!(replay(&f[..1],&seed(),limits()).unwrap_err(),Error::Identity);}}
#[test] fn no_native_binding_or_ready_authority_from_journal(){assert_eq!(require_native_binding(),Err(Error::Unsupported));let r=replay(&frames(),&seed(),limits()).unwrap();assert_eq!(r.phase,Phase::ReadyRecordDecoded);assert!(r.commit.is_some());assert!(r.prepared.is_some());assert_eq!(require_native_binding(),Err(Error::Unsupported));}
#[test] fn directories_have_distinct_target_and_no_link_counters(){let mut f=frames();let mut i=intent(&f[0]).clone();let p=&mut i.plan[0];p.path="app".into();p.kind=2;p.mode=0o700;p.size=0;p.content=None;i.seal=plan_seal(&i.plan,limits()).unwrap();let p=i.plan[0].clone();f[0].record.event=Event::Intent(i);f[3].record.event=Event::OpIntent{index:0,item:p.clone(),expected_absent:1};f[4].record.event=Event::OpRecorded{index:0,item:ActualItem{path:p.path,kind:2,source:p.source,target:id(8),mode:p.mode,size:0,content:None,before:None,after:None}};rebind(&mut f);assert_eq!(replay(&f[..5],&seed(),limits()).unwrap().phase,Phase::Publishing);for mode in 0..3{let mut bad=f.clone();if let Event::OpRecorded{item,..}=&mut bad[4].record.event{match mode{0=>item.target=item.source,1=>item.target=id(6),_=>item.before=Some(1)}}resign(&mut bad,&seed());fail(&bad[..5]);}}
#[test] fn duplicate_target_cannot_consume_two_plan_items(){let mut f=frames();let mut i=intent(&f[0]).clone();let mut p=i.plan[0].clone();p.path="app/other.txt".into();p.source=id(8);i.plan.push(p.clone());i.seal=plan_seal(&i.plan,limits()).unwrap();f[0].record.event=Event::Intent(i);f.truncate(5);let a=if let Event::OpRecorded{item,..}=&f[4].record.event{item.clone()}else{panic!("fixture")};let mut h=f[4].record.header.clone();h.seq=6;f.push(Frame{record:Record{header:h.clone(),event:Event::OpIntent{index:1,item:p.clone(),expected_absent:1}},sha:[0;32]});h.seq=7;let mut next=a;next.path=p.path;next.source=p.source;next.target=p.source;f.push(Frame{record:Record{header:h,event:Event::OpRecorded{index:1,item:next}},sha:[0;32]});rebind(&mut f);assert!(replay(&f,&seed(),limits()).is_ok());if let Event::OpRecorded{item,..}=&mut f[6].record.event{item.target=id(5)}resign(&mut f,&seed());fail(&f);
    // Keep the file source/target mismatch negative above. This separate
    // directory fixture passes actual_ok and isolates targets.contains.
    let mut unique=frames();
    let mut i=intent(&unique[0]).clone();
    let mut directory=i.plan[0].clone();
    directory.path="app/other.txt".into();
    directory.kind=2;
    directory.mode=0o700;
    directory.size=0;
    directory.content=None;
    directory.source=id(8);
    i.plan.push(directory.clone());
    let mut plan_bytes=Vec::new();
    w32(&mut plan_bytes,i.plan.len().try_into().unwrap());
    for item in &i.plan { wplan(&mut plan_bytes,item); }
    i.seal=dh("openbot.release-plan.v1",&plan_bytes);
    unique[0].record.event=Event::Intent(i);
    unique.truncate(5);
    let mut header=unique[4].record.header.clone();
    header.seq=6;
    unique.push(Frame{record:Record{header:header.clone(),event:Event::OpIntent{index:1,item:directory.clone(),expected_absent:1}},sha:[0;32]});
    header.seq=7;
    unique.push(Frame{record:Record{header,event:Event::OpRecorded{index:1,item:ActualItem{path:directory.path,kind:2,source:id(8),target:id(9),mode:0o700,size:0,content:None,before:None,after:None}}},sha:[0;32]});
    rebind(&mut unique);
    assert!(replay(&unique,&seed(),limits()).is_ok());
    let prefix=replay(&unique,&seed(),limits()).unwrap();
    assert_eq!(prefix.phase,Phase::Publishing);
    assert_eq!(prefix.pending,None);
    // No COMMIT: only the second target changes, from unused id9 to consumed id5.
    if let Event::OpRecorded{item,..}=&mut unique[6].record.event { item.target=id(5); }
    resign(&mut unique,&seed());
    assert_eq!(replay(&unique,&seed(),limits()).unwrap_err(),Error::Identity);
}
#[test] fn strict_order_does_not_normalize_or_trim_versions(){let mut f=frames();let mut i=intent(&f[0]).clone();i.version=" v1 ".into();f[0].record.event=Event::Intent(i);rebind(&mut f);assert_eq!(replay(&f[..1],&seed(),limits()).unwrap().phase,Phase::IntentFixed);if let Event::Commit{version,..}=&mut f[5].record.event{*version="v1".into()}resign(&mut f,&seed());fail(&f[..6]);}
